import type { Route, RouteContext } from '@superfunctions/http';
import { ErrorCode } from '@recfn/core';
import type { RecFnStore } from '../store/types.js';
import type { ValidateApiKey } from '../middleware/auth.js';
import { authenticate } from '../middleware/auth.js';
import { ok, err } from '../middleware/envelope.js';

export interface ChatRouteDeps {
  store: RecFnStore;
  validateApiKey: ValidateApiKey;
}

export function createChatRoutes(deps: ChatRouteDeps): Route[] {
  const { store, validateApiKey } = deps;

  return [
    {
      method: 'GET',
      path: '/api/v1/bots/:botId/chat',
      handler: async (request: Request, ctx: RouteContext) => {
        const auth = await authenticate(request, validateApiKey);
        const bot = await store.getBot(ctx.params.botId, auth.namespace);
        if (!bot) {
          return err(ErrorCode.BOT_NOT_FOUND, 'Bot not found.');
        }
        const messages = await store.getChatMessages(
          ctx.params.botId,
          auth.namespace,
        );
        return ok({ messages });
      },
    },
  ];
}
import type { Route, RouteContext } from '@superfunctions/http';
import { computeAnalytics } from '@recfn/core';
import { ErrorCode } from '@recfn/core';
import type { RecFnStore } from '../store/types.js';
import type { ValidateApiKey } from '../middleware/auth.js';
import { authenticate } from '../middleware/auth.js';
import { ok, err } from '../middleware/envelope.js';

export interface AnalyticsRouteDeps {
  store: RecFnStore;
  validateApiKey: ValidateApiKey;
}

export function createAnalyticsRoutes(deps: AnalyticsRouteDeps): Route[] {
  const { store, validateApiKey } = deps;

  return [
    {
      method: 'GET',
      path: '/api/v1/recordings/:recordingId/analytics',
      handler: async (request: Request, ctx: RouteContext) => {
        const auth = await authenticate(request, validateApiKey);
        const recordingId = ctx.params.recordingId;

        const recording = await store.getRecording(recordingId, auth.namespace);
        if (!recording) {
          return err(ErrorCode.RECORDING_NOT_FOUND, 'Recording not found.');
        }

        const transcript = await store.getTranscript(recordingId, auth.namespace);
        if (!transcript) {
          return err(
            ErrorCode.ANALYTICS_NOT_READY,
            'Transcript not ready. Analytics require a completed transcript.',
          );
        }

        if (transcript.status !== 'ready') {
          return err(
            ErrorCode.ANALYTICS_NOT_READY,
            'Transcript not ready. Analytics require a completed transcript.',
          );
        }

        const analytics = computeAnalytics(
          recordingId,
          transcript.segments,
          recording.duration,
        );

        return ok(analytics);
      },
    },
  ];
}
import { type ErrorCodeType, ErrorHttpStatus } from '@recfn/core';
import { createErrorRegistry } from '@superfunctions/errors';
import { err as createEnvelopeError, ok as createEnvelopeSuccess, toLegacyDataEnvelope } from '@superfunctions/envelope';

const errorRegistry = createErrorRegistry(
  Object.entries(ErrorHttpStatus).map(([code, httpStatus]) => ({
    code,
    httpStatus: Number(httpStatus),
    retryable: Number(httpStatus) >= 500 || Number(httpStatus) === 429,
  }))
);

export function ok<T>(data: T, status = 200): Response {
  const canonical = createEnvelopeSuccess(data);
  return Response.json(toLegacyDataEnvelope(canonical), { status });
}

export function err(
  code: ErrorCodeType,
  message: string,
  details?: Record<string, unknown>,
  status?: number,
): Response {
  const resolved = errorRegistry.resolveOrDefault(code, {
    httpStatus: status ?? ErrorHttpStatus[code] ?? 500,
    retryable: (status ?? ErrorHttpStatus[code] ?? 500) >= 500 || (status ?? ErrorHttpStatus[code] ?? 500) === 429,
  });
  const canonical = createEnvelopeError({
    code,
    message,
    status: resolved.httpStatus,
    retryable: resolved.retryable,
    details: details ?? {},
  });

  return Response.json(toLegacyDataEnvelope(canonical), { status: canonical.error.status });
}
